<?php $title='Benachrichtigungen'; ?>
<div class="page-header split"><div><p class="eyebrow">Benachrichtigungen</p><h1>Interne Hinweise</h1><p>Rollen- und ereignisabhängige Benachrichtigungen für den aktiven Standort.</p></div><form method="post" action="<?= e(url('notifications/read-all')) ?>"><?= csrf_field() ?><button class="button ghost" type="submit">Alle als gelesen markieren</button></form></div>
<div class="panel"><div class="timeline-list"><?php foreach($items as $n):?><div class="timeline-item" style="<?= $n['read_at']?'opacity:.72':'' ?>"><div class="split"><strong><?= e($n['title']) ?></strong><?php if(!$n['read_at']):?><span class="badge <?= $n['severity']==='important'?'warning':'active' ?>">Neu</span><?php endif;?></div><div class="prose"><?= e($n['message']) ?></div><small class="table-sub"><?= e(format_datetime($n['created_at'])) ?><?= $n['location_name']?' · '.e($n['location_name']):'' ?></small><?php if($n['target_url']):?><form method="post" action="<?= e(url('notifications/'.$n['id'].'/read')) ?>" style="margin-top:8px"><?= csrf_field() ?><input type="hidden" name="target" value="<?= e($n['target_url']) ?>"><button class="button secondary compact" type="submit">Öffnen</button></form><?php elseif(!$n['read_at']):?><form method="post" action="<?= e(url('notifications/'.$n['id'].'/read')) ?>" style="margin-top:8px"><?= csrf_field() ?><button class="button ghost compact" type="submit">Als gelesen markieren</button></form><?php endif;?></div><?php endforeach;?><?php if($items===[]):?><div class="empty">Keine Benachrichtigungen vorhanden.</div><?php endif;?></div></div>
